def generate_short_link_code():
    """Генерирует случайный код для короткой ссылки на рецепт."""
    alphabet = string.ascii_letters + string.digits
    return ''.join(random.choices(alphabet, k=6))


def populate_short_links(apps, schema_editor):
    """Заполняет короткие ссылки для уже существующих рецептов."""
    Recipe = apps.get_model('recipes', 'Recipe')
    existing_codes = set(
        Recipe.objects.exclude(short_link='').values_list(
            'short_link', flat=True
        )
    )
    for recipe in Recipe.objects.filter(short_link=''):
        code = generate_short_link_code()
        while code in existing_codes:
            code = generate_short_link_code()
        existing_codes.add(code)
        recipe.short_link = code
        recipe.save(update_fields=['short_link'])


